template:
PREFIX s: <https://schema.org/>
PREFIX seeds: <https://seeds.local/ontology/>
SELECT DISTINCT ?item ?id ?status ?title ?description ?owner ?modified ?label ?type
FROM <{board}>
WHERE {
 ?item s:identifier "{identifier}" ; s:identifier ?id ; s:keywords ?label .
 OPTIONAL { ?item a ?type }
 OPTIONAL { ?item seeds:status ?status }
 OPTIONAL { ?item s:name ?title }
 OPTIONAL { ?item s:dateModified ?modified }
 FILTER(?label IN ("stiwi-directive", "design", "plan"))
 OPTIONAL { ?item s:description ?description }
 OPTIONAL { ?item s:agent ?owner }

}
ORDER BY ?item ?label
LIMIT 101
